## Analysis & Pre-Thinking

- **Core Requirements**: Fix the Views system — loading, saving, deleting, and applying desktop layouts per project
- **Strategic Approach**:
  - Audit the full data flow: store → API → backend → frontend rendering
  - Identify broken wiring between `ui.js` store (which has view-related state/methods mixed in) and the new `views.js` store
  - Fix `ViewsMenu.vue` which references `$storex.ui.views` but views are in `$storex.views`
  - Fix `views.js` store — `state` referenced directly in actions (wrong pattern), `deleteView` signature mismatch, `onActiveProjectChanged` uses stale `state`
  - Fix `Desktop.vue` — `restoreLayout` needs to integrate with views store on load
  - Ensure `views.js` store is registered and `init` is called
- **Dependencies & Risks**:
  - `ViewsMenu.vue` calls `$storex.ui.views`, `$storex.ui.lastView`, `$storex.ui.saveView`, `$storex.ui.loadView`, `$storex.ui.deleteView` — all wrong namespace
  - `views.js` actions access `state` directly (not from action context) — bug in typed-vuex pattern
  - `deleteView` in store takes `{ viewName, projectId }` but `ViewsMenu` calls `deleteView(view.name)` — mismatch
  - `Desktop.vue` `restoreLayout` doesn't check views store at all
  - `views.js` `init` subscribes to store mutations but `$storex.store` may not exist
  - `ui.js` still has `viewEditor`, `views`, `lastView`, `saveView`, `loadView`, `deleteView` scattered — need to unify
- **Target Files**:
  - `client/src/store/views.js` — major fixes
  - `client/src/components/main-menu/ViewsMenu.vue` — fix store references
  - `client/src/components/desktop/Desktop.vue` — integrate views store on layout restore

---

## File 1: `client/src/store/views.js`

Key fixes:
- Actions must use `({ state })` destructuring to access state correctly
- Remove broken `$storex.store.subscribe` (doesn't exist in typed-vuex pattern)
- Fix `deleteView` to accept plain `viewName` string (match what ViewsMenu sends)
- Fix `onActiveProjectChanged` state access
- Simplify and make robust

```js client/src/store/views.js
import { getterTree, mutationTree, actionTree } from 'typed-vuex'
import { $storex } from '.'
import { API } from '../api/api'

export const namespaced = true

export const state = () => ({
  views: [],
  currentView: null,
  lastView: null
})

export const getters = getterTree(state, {
  viewNames: state => state.views.map(v => v.name),
  hasViews: state => state.views.length > 0,
  currentViewName: state => state.currentView?.name || null,
})

export const mutations = mutationTree(state, {
  setViews(state, views) {
    state.views = views || []
  },
  setCurrentView(state, view) {
    state.currentView = view || null
  },
  setLastView(state, view) {
    state.lastView = view || null
  },
  upsertView(state, view) {
    // Replace existing by name, or append
    const index = state.views.findIndex(v => v.name === view.name)
    if (index >= 0) {
      state.views.splice(index, 1, view)
    } else {
      state.views.push(view)
    }
  },
  removeView(state, viewName) {
    state.views = state.views.filter(v => v.name !== viewName)
  }
})

export const actions = actionTree(
  { state, getters, mutations },
  {
    async init({ state }) {
      await $storex.views.loadViews()
    },

    // Reload views when active project changes
    async onActiveProjectChanged({ state }) {
      $storex.views.setCurrentView(null)
      $storex.views.setLastView(null)
      await $storex.views.loadViews()
    },

    async loadViews({ state }) {
      try {
        const api = $storex.projects?.activeProject?.$api || API
        const views = await api.views.list()
        $storex.views.setViews(views || [])
      } catch (error) {
        console.error('Failed to load views:', error)
        $storex.views.setViews([])
      }
    },

    // Save current dockview layout under the given name
    async saveView({ state }, viewName) {
      try {
        const desktopApi = $storex.ui._desktopApi
        if (!desktopApi) throw new Error('Desktop API not available')

        const layout = desktopApi.toJSON()
        const projectId = $storex.projects?.activeProject?.project_id
        const api = $storex.projects?.activeProject?.$api || API

        const view = {
          name: viewName,
          layout,
          project_id: projectId,
          last_update: Date.now()
        }

        const saved = await api.views.save(view)
        $storex.views.upsertView(saved || view)
        $storex.views.setLastView(saved || view)
        return saved || view
      } catch (error) {
        console.error('Failed to save view:', error)
        throw error
      }
    },

    // Apply a saved view's layout to the desktop
    async loadView({ state }, view) {
      try {
        $storex.views.setCurrentView(view)
        $storex.views.setLastView(view)

        const desktopApi = $storex.ui._desktopApi
        if (view.layout && desktopApi) {
          desktopApi.fromJSON(view.layout)
        }
      } catch (error) {
        console.error('Failed to load view:', error)
        throw error
      }
    },

    async deleteView({ state }, viewName) {
      try {
        const api = $storex.projects?.activeProject?.$api || API
        await api.views.delete(viewName)
        $storex.views.removeView(viewName)

        // Clear current/last if they match the deleted view
        if (state.currentView?.name === viewName) {
          $storex.views.setCurrentView(null)
        }
        if (state.lastView?.name === viewName) {
          $storex.views.setLastView(null)
        }
      } catch (error) {
        console.error('Failed to delete view:', error)
        throw error
      }
    },

    async renameView({ state }, { oldName, newName }) {
      try {
        const api = $storex.projects?.activeProject?.$api || API
        const updated = await api.views.rename(oldName, newName)

        // Update local state with renamed view
        const existing = state.views.find(v => v.name === oldName)
        if (existing) {
          const renamedView = updated || { ...existing, name: newName }
          $storex.views.removeView(oldName)
          $storex.views.upsertView(renamedView)

          if (state.currentView?.name === oldName) {
            $storex.views.setCurrentView(renamedView)
          }
          if (state.lastView?.name === oldName) {
            $storex.views.setLastView(renamedView)
          }
        }
      } catch (error) {
        console.error('Failed to rename view:', error)
        throw error
      }
    },

    // Save over the currently active view (quick-save)
    async saveCurrentView({ state }) {
      const view = state.lastView || state.currentView
      if (!view?.name) return
      await $storex.views.saveView(view.name)
    }
  }
)
```

